-- 고성·양양 명소를 "가볼만한 곳"에 올린다(2026-11-22 사용자 요청). 구조는 바꾸지 않고 값만 넣는다.
-- 행사 상세의 "주변 명소"를 뺀 뒤(2026-11-21) 분류(activity_category)가 비어 어디에도 보이지 않던 고성·양양 명소 63곳에
-- 분류·새 slug·한 줄 소개·소개·운영시간·휴무·요금·주차·주의할 점·실제 주소와 좌표·사진을 채우고, 새 장소 2곳(공현진2리해변·반비치)을 넣는다.
-- 다른 항목과 같은 곳(의상대·홍련암, 진전사, 오산리 선사유적, 송지호 비지터센터)과 찾아갈 장소가 아닌 곳(국도 7호선 종점, 화진포 역사안보전시관, 아야진등대) 8곳은
-- 그대로 둔다(분류가 비어 화면에 나오지 않음).
-- 원본은 data/activity-places.json이고, 사진 파일은 public/places/<slug>.webp와 -thumb.webp로 함께 배포한다.
-- 20261122041307_unify_place_text_tone.sql 뒤에 적용한다.
-- 운영에서 관리자가 고친 장소는 덮어쓰지 않도록, 분류가 비어 있고 이름·주소가 앞 migration이 넣은 값 그대로인 행만 바꾼다
-- (결정 docs/decisions/conventions.md "장소 데이터의 원본": update는 앞 값이 그대로일 때만, 2026-11-22 리뷰).
-- 관리자가 이름·주소를 고친 행은 바뀌지 않고 분류가 빈 채로 남는다(화면에 안 보임). 적용 뒤 확인 SQL로 찾아 관리자 화면에서 채운다.
-- 새 장소는 같은 slug가 있으면 넣지 않는다.

update public.places set slug = 'cheonjin-beach', summary = '천진항 옆, 물이 얕고 파도가 잔잔한 초승달 해변', address = '강원특별자치도 고성군 토성면 천진리', latitude = 38.259935, longitude = 128.560305, image_url = '/places/cheonjin-beach.webp', image_credit = '사진: 고성군 관광포털', image_source_url = 'https://www.gwgs.go.kr/prog/tursmCn/tour/sub02_02/view.do?cntno=81', image_alt = '초록 그늘막이 줄지어 선 천진해변 백사장과 해변 마을', activity_category = 'nature', tags = array['free', 'kids'], description = '천진항과 붙어 초승달 모양으로 휘어진 해변으로, 전체적으로 물이 얕고 파도가 잔잔해 아이들이 놀기 좋아요. 방파제 낚시와 천진항 활어회를 함께 즐길 수 있고, 2025년 여름에는 섭죽 만들기 같은 마을 체험 축제가 열리기도 했어요. 고성에서 해마다 일찍 문을 여는 해변 가운데 하나예요.', hours_summary = '물놀이는 여름 개장 기간(6월 하순~8월 말)에만 가능', price_summary = '무료(샤워장·파라솔·야영장은 유료)', phone = '033-680-3356', parking_summary = '주차 가능', cautions = '개장 기간이 아니면 안전요원이 없어 물에 들어가지 마세요.', verified_on = '2026-11-21'
