update public.places set slug = 'dongsan-port', summary = '물이 맑고 잔잔해 낚시·다이빙을 즐기는 작은 항구', address = '강원특별자치도 양양군 현남면 동산리 137-12', latitude = 37.979445, longitude = 128.762286, image_url = '/places/dongsan-port.webp', image_credit = '사진: 양양군 문화관광', image_source_url = 'https://tour.yangyang.go.kr/pub/yysea.do?mode=v&seq=140', image_alt = '맑은 날 동산항에 정박한 어선들과 항구 뒤 숲 언덕', activity_category = 'nature', tags = array['free'], description = '파도가 잔잔하고 물이 얕은 작은 항구로, 봄이면 임연수와 도다리를 낚으러 오는 사람이 많고 배낚시도 이곳에서 나가요. 물이 맑아 스쿠버다이빙을 하러도 찾으며, 300m 길이의 방파제를 따라 걸으며 바다를 볼 수 있어요. 바로 옆 동산해변·죽도해변과 함께 둘러보기 좋아요.', price_summary = '무료', phone = '033-670-2411', verified_on = '2026-11-21'
where slug = 'yangyang-attraction-121' and activity_category is null and name is not distinct from '동산항' and address is not distinct from '강원특별자치도  양양군  현남면  동산리  동산큰길 동산항교차로';
insert into public.places (id, slug, name, category, summary, address, latitude, longitude, image_url, image_credit, image_source_url, image_alt, official_url, map_url, is_published, activity_category, tags, description, hours_summary, closed_summary, price_summary, phone, parking_summary, cautions, booking_url, operation_status, status_note, status_note_until, verified_on)
values ('20000000-0000-4000-8000-000000000302', 'banbeach', '반비치', '반려견 해변', '반려견이 목줄 없이 뛰노는 강원 첫 반려동물 해변', '강원특별자치도 고성군 거진읍 자산천로 102-16', 38.424284, 128.461040, '/places/banbeach.webp', '사진: 고성군, 공공누리 제1유형(KOGL Type 1)', 'https://www.gwgs.go.kr/prog/bbsArticle/BBSMSTR_000000003771/view.do?nttId=B000000064561Dr4bI2h', '나무 울타리로 둘러싼 모래밭과 분홍 파라솔 너머로 방파제와 빨간 등대가 보이는 반비치', 'https://www.instagram.com/banbeach_gosung/', 'https://map.naver.com/p/search/%EB%B0%98%EB%B9%84%EC%B9%98', true, 'nature', '{}', '고성군이 2024년 8월 거진읍 반암리에 연 강원도 첫 반려동물 동반 해수욕장으로, 울타리를 친 모래밭에서 반려견이 목줄 없이 뛰고 바다에도 들어갈 수 있어요. 반려견 크기별로 구역을 나누고, 반려견 전용 온수 샤워장과 건조기를 갖췄어요. 같은 반암리의 일반 해수욕장인 반암해변과는 공간이 분리돼 있어, 개와 함께 바다를 즐기고 싶은 보호자에게 맞아요.', '10:00~18:00(입장 마감 17:00). 여름 해수욕장 개장 때부터 가을까지 운영(2025년은 10월 30일까지)', null, '반려견 한 마리 소·중형견 10,000원, 대형견 15,000원(보호자 무료). 샤워실·파라솔은 별도', '0507-1397-6661', '반암항 낚시공원 앞 주차장 이용(무료)', '동물등록을 한 반려견만 들어갈 수 있어요.
해변 안에서는 음식을 먹거나 담배를 피울 수 없고, 간식·사료·음료도 가지고 들어갈 수 없어요.
운영 기간과 시간이 해마다 바뀌니 공식 인스타그램(@banbeach_gosung)에서 먼저 확인하세요.', null, 'open', null, null, '2026-11-22')
on conflict (slug) do nothing;
